    else await page.goto(origin,{waitUntil:'domcontentloaded'});
    activeOrigin=origin;
    await page.locator('#case-search').waitFor({state:'visible'});
    await page.waitForFunction(()=>document.querySelector('#case-save')?.disabled===false);
